-- submissions/crash-source-count
-- How many sources a crash has, to set its verification level when it is published or gains a source.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

select count(*)
from "crash_sources"
where "crash_sources"."crash_id" = $1;
